using EduCenterManagement.Data;using EduCenterManagement.Enums;using EduCenterManagement.Models;using Microsoft.EntityFrameworkCore;
namespace EduCenterManagement.DevSupport;
public static class DevSeedComments { public static async Task SeedAsync(ApplicationDbContext db,CancellationToken ct=default){var parent=await db.ParentProfiles.SingleAsync(x=>x.User.Email=="seed.parent@ecm.test",ct);var students=await db.ParentStudentLinks.Where(x=>x.ParentId==parent.Id&&x.Status==ParentStudentLinkStatus.Accepted).Select(x=>x.Student).OrderBy(x=>x.Id).ToListAsync(ct);foreach(var student in students){var classes=await db.Enrollments.Where(x=>x.StudentId==student.Id&&x.Status==EnrollmentStatus.Confirmed&&x.Class.TeacherId!=null).Select(x=>x.Class).Take(2).ToListAsync(ct);for(var i=0;i<3;i++){var c=classes[i%classes.Count];if(!await db.TeacherComments.AnyAsync(x=>x.TeacherId==c.TeacherId&&x.StudentId==student.Id&&x.ClassId==c.Id&&x.Content=="Seed comment "+(i+1),ct)){db.TeacherComments.Add(new TeacherComment{TeacherId=c.TeacherId!.Value,StudentId=student.Id,ClassId=c.Id,Rating=i+3>5?5:i+3,Content="Seed comment "+(i+1),Visibility="parent_student"});}}}await db.SaveChangesAsync(ct);} }
